  let totalReceived = 0;
  let totalPending = 0;
  let lastPaymentDate = null;
  let receivedTripsCount = 0;
  let pendingTripsCount = 0;
  let totalPaymentDaysSum = 0;
  let paidTripsWithDurationCount = 0;
  let onTimeTripsCount = 0;
